 void Add(TableLayoutPanel p,Control c,int height){int row=p.RowCount-1;p.RowStyles.Add(new RowStyle(SizeType.Absolute,height));c.Dock=DockStyle.Fill;p.Controls.Add(c,0,row);p.RowCount++;}
